// Replays testdata/tee_verdict_vectors.json, generated by
// proto/go/zs/tee/verdict_vectors_test.go, through the TypeScript
// BundleVerifier. Go and TypeScript then reach one verdict on the same bundle
// bytes, configuration and chain outcome, rather than each agreeing with its
// own suite. Regenerate with
// `cd proto/go && go test ./zs/tee -run TestVerdictVectors -update`.
//
// The bundle goes through decodeEvidenceBundle, so a case pins the decoder and
// the verifier together, as a payer meets them.

import { readFileSync } from 'node:fs'
import { describe, expect, it, vi } from 'vitest'

// Every case injects both chain seams. Were one left out, the real verifier
// would fetch; this makes that a loud failure rather than a network call.
vi.mock('@phala/dcap-qvl', () => ({
    default: {
        PHALA_PCCS_URL: 'https://unreachable.invalid',
        getCollateral: () => Promise.reject(new Error('a verdict vector reached dcap-qvl getCollateral')),
        verify: () => {
            throw new Error('a verdict vector reached dcap-qvl verify')
        },
    },
}))

import {
    type ComposePolicy,
    EMBEDDED_COLLATERAL_MAX_AGE_MS,
    trustedComposeSkeletons,
    trustedNodeImages,
    zeroSignalComposePolicy,
} from '@txnlab/zs-proto/attest'
import { type TEEAdvertisement, decodeEvidenceBundle } from '@txnlab/zs-proto/inject'

import {
    ACCEPTED_TCB_STATUS,
    BundleVerifier,
    type CarriedChainVerifier,
    type ChainResult,
    CollateralUnavailableError,
    EVIDENCE_MAX_AGE_CEILING_MS,
    FailureTag,
    type QuoteChainVerifier,
    StaleCollateralRejectedError,
    VERIFIER_ID_BUILTIN,
    VERIFIER_ID_DSTACK,
} from '../src/tee/index.js'

interface VerdictCase {
    name: string
    advertisement: TEEAdvertisement
    bundle: Record<string, unknown>
    cpu_report_quote?: string
    cpu_report?: string
    event_log?: string
    generated_at_offset_ms: number | null
    node: { operator_id: string; node_id: string; ephemeral_recipient_pubkey: string }
    policy: {
        trusted_os_images: string[]
        trusted_compose_hashes: string[]
        compose_policy: string
        trusted_compose_skeletons?: string[]
        trusted_node_images?: string[]
    }
    allow_stub: boolean
    chain: string
    carried: string
    collateral: string
    now_unix_ms: number
    expect: Expected
}

interface Expected {
    pass: boolean
    /** null: refused, tag not asserted (SPEC § 3e step 2 leaves it open). */
    failure_tag: string | null
    verifier_id: string
    attested_model_ids: string[] | null
    carried_called: boolean
}

interface VerdictVectors {
    constants: {
        evidence_max_age_ceiling_ms: number
        embedded_collateral_max_age_ms: number
        accepted_tcb_status: string
        failure_tags: Record<string, string>
        verifier_ids: Record<string, string>
    }
    quotes: Record<string, string>
    event_logs: Record<string, string>
    cases: VerdictCase[]
}

const vectors = JSON.parse(
    readFileSync(new URL('../../testdata/tee_verdict_vectors.json', import.meta.url), 'utf8'),
) as VerdictVectors

function composePolicy(p: VerdictCase['policy']): ComposePolicy {
    switch (p.compose_policy) {
        case 'none':
            return {}
        case 'shape_only':
            return { ...zeroSignalComposePolicy(), enforceComposeSkeleton: false }
        case 'shipped':
            return {
                ...zeroSignalComposePolicy(),
                enforceComposeSkeleton: true,
                trustedComposeSkeletons: trustedComposeSkeletons(),
                trustedNodeImages: trustedNodeImages(),
            }
        case 'release':
            return {
                ...zeroSignalComposePolicy(),
                enforceComposeSkeleton: true,
                trustedComposeSkeletons: p.trusted_compose_skeletons ?? [],
                trustedNodeImages: p.trusted_node_images ?? [],
            }
    }
    throw new Error(`unknown compose policy ${p.compose_policy}`)
}

// The TypeScript chain verifier reports a TCB status where go-tdx-guest
// refuses inside the chain check; DstackVerifier turns the status into Go's
// tag, which is what the vector holds it to.
function chainVerifier(outcome: string): QuoteChainVerifier {
    const status = (prefix: string) => outcome.slice(prefix.length)
    return async (): Promise<ChainResult> => {
        if (outcome === 'ok') return { tcbStatus: 'UpToDate', advisoryIds: [] }
        if (outcome === 'unavailable') {
            // Wrapped, as Go wraps with %w, so the cause walk is what finds it.
            throw new Error('pccs fetch failed', {
                cause: new CollateralUnavailableError(new Error('dial tcp: no route to host')),
            })
        }
        if (outcome === 'stale_rejected') {
            throw new StaleCollateralRejectedError(new Error('pcs down'), new Error('crl expired'))
        }
        if (outcome === 'invalid') throw new Error('tdx quote verification: signature mismatch')
        if (outcome.startsWith('tcb:')) return { tcbStatus: status('tcb:'), advisoryIds: [] }
        if (outcome.startsWith('stale_tcb:')) {
            return { tcbStatus: status('stale_tcb:'), advisoryIds: [], servedStale: true }
        }
        throw new Error(`unknown chain outcome ${outcome}`)
    }
}

function carriedVerifier(outcome: string, onCall: () => void): CarriedChainVerifier {
    return async (): Promise<ChainResult> => {
        onCall()
        if (outcome === 'ok') return { tcbStatus: 'UpToDate', advisoryIds: [] }
        if (outcome === 'invalid') throw new Error('tdx quote verification: chain does not root at Intel')
        if (outcome.startsWith('tcb:')) return { tcbStatus: outcome.slice('tcb:'.length), advisoryIds: [] }
        throw new Error(`unknown carried outcome ${outcome}`)
    }
}

/** The body a node would serve: the case's bundle plus the three fields the replay supplies. */
function body(c: VerdictCase): Uint8Array {
    const b: Record<string, unknown> = { ...c.bundle }
    if (c.cpu_report_quote !== undefined) {
        const q = vectors.quotes[c.cpu_report_quote]
        if (q === undefined) throw new Error(`no quote named ${c.cpu_report_quote}`)
        b['cpu_report'] = q
    } else if (c.cpu_report !== undefined) {
        b['cpu_report'] = c.cpu_report
    }
    if (c.event_log !== undefined) {
        const l = vectors.event_logs[c.event_log]
        if (l === undefined) throw new Error(`no event log named ${c.event_log}`)
        b['event_log'] = l
    }
    if (c.generated_at_offset_ms !== null) {
        b['generated_at'] = new Date(c.now_unix_ms + c.generated_at_offset_ms).toISOString()
    }
    return new TextEncoder().encode(JSON.stringify(b))
}

async function replay(c: VerdictCase): Promise<Expected> {
    const bundle = decodeEvidenceBundle(body(c))
    let carriedCalled = false
    const v = new BundleVerifier({
        allowStub: c.allow_stub,
        trustedOSImages: c.policy.trusted_os_images,
        trustedComposeHashes: c.policy.trusted_compose_hashes,
        composePolicy: composePolicy(c.policy),
        verifyChain: chainVerifier(c.chain),
        verifyChainCarried: carriedVerifier(c.carried, () => {
            carriedCalled = true
        }),
        now: () => c.now_unix_ms,
    })
    const verdict = await v.verify(c.advertisement, bundle, {
        operatorId: BigInt(c.node.operator_id),
        nodeId: BigInt(c.node.node_id),
        ephemeralRecipientPubkey: c.node.ephemeral_recipient_pubkey,
    })
    return {
        pass: verdict.pass,
        failure_tag: verdict.failureTag,
        verifier_id: verdict.verifierId,
        attested_model_ids: verdict.attestedModelIds ?? null,
        carried_called: carriedCalled,
    }
}

describe('tee_verdict_vectors.json constants', () => {
    const k = vectors.constants

    it('agree with the verifier exports', () => {
        expect(EVIDENCE_MAX_AGE_CEILING_MS).toBe(k.evidence_max_age_ceiling_ms)
        expect(EMBEDDED_COLLATERAL_MAX_AGE_MS).toBe(k.embedded_collateral_max_age_ms)
        expect(ACCEPTED_TCB_STATUS).toBe(k.accepted_tcb_status)
        expect(VERIFIER_ID_BUILTIN).toBe(k.verifier_ids['builtin'])
        expect(VERIFIER_ID_DSTACK).toBe(k.verifier_ids['dstack'])
    })

    it('name exactly the failure tags Go declares', () => {
        // Both directions: a tag only one side knows is a dashboard handle the
        // other can never emit.
        expect({ ...FailureTag }).toEqual(k.failure_tags)
    })
})

describe('tee_verdict_vectors.json cases', () => {
    it('has cases to replay', () => {
        expect(vectors.cases.length).toBeGreaterThan(0)
    })

    it.each(vectors.cases.map((c) => [c.name, c] as const))('%s', async (_name, c) => {
        const got = await replay(c)
        if (c.expect.failure_tag === null) {
            expect(got.pass).toBe(false)
            expect(got.failure_tag).not.toBe('')
            got.failure_tag = null
        }
        expect(got).toEqual(c.expect)
    })
})
